import numpy as np
def equation(t, A, params):
    p = params
    terms = [p[0]]
    k = 1
    for i in range(3):
        for j in range(4):
            if i == 0 and j == 0:
                continue
            terms.append(p[k]*t**i*A**j); k += 1
    terms.append(p[k]*np.exp(-0.5*t)*A**2)
    return sum(terms)
